	/*
     * @param	event CreateAgentEvent
     */
    @EventHandler( payloadType=CreateAgentEvent.class )
    public void handle( CreateAgentEvent event) {
	    LOGGER.info("handling CreateAgentEvent - " + event );
	    Agent entity = new Agent();
            entity.setAgentId( event.getAgentId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setLicenseId( event.getLicenseId() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAgent( entity );
    }

    /*
     * @param	event UpdateAgentEvent
     */
    @EventHandler( payloadType=UpdateAgentEvent.class )
    public void handle( UpdateAgentEvent event) {
    	LOGGER.info("handling UpdateAgentEvent - " + event );
    	
	    Agent entity = new Agent();
            entity.setAgentId( event.getAgentId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setLicenseId( event.getLicenseId() );
            entity.setDistributor( event.getDistributor() );
            entity.setPolicies( event.getPolicies() );
            entity.setCustomers( event.getCustomers() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindAgent( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAgent( entity );        
    }
    
