    /**
     * Method to retrieve the Agent via an AgentPrimaryKey.
     * @param 	id Long
     * @return 	Agent
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Agent handle( FindAgentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAgentId() );
    }
    
    /**
     * Method to retrieve a collection of all Agents
     *
     * @param	query	FindAllAgentQuery 
     * @return 	List<Agent> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Agent> handle( FindAllAgentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAgent,
 * but only if the id matches
 *
 * @param		entity	Agent
 */
	protected void emitFindAgent( Agent entity ) {
		LOGGER.info("handling emitFindAgent" );
		
	    queryUpdateEmitter.emit(FindAgentQuery.class,
	                            query -> query.getFilter().getAgentId().equals(entity.getAgentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAgent
	 * 
	 * @param		entity	Agent
	 */
	protected void emitFindAllAgent( Agent entity ) {
		LOGGER.info("handling emitFindAllAgent" );
		
	    queryUpdateEmitter.emit(FindAllAgentQuery.class,
	                            query -> true,
	                            entity);
	}

